"""Tokenizer, AST and parser for the minisql ``SELECT`` dialect."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, List, Optional


class QueryError(Exception):
    """Raised for any problem with a query."""


# ---------------------------------------------------------------------------
# Tokens


KEYWORDS = {
    "SELECT",
    "DISTINCT",
    "FROM",
    "WHERE",
    "GROUP",
    "BY",
    "HAVING",
    "ORDER",
    "LIMIT",
    "OFFSET",
    "ASC",
    "DESC",
    "AS",
    "AND",
    "OR",
    "NOT",
    "IN",
    "BETWEEN",
    "LIKE",
    "IS",
    "NULL",
    "TRUE",
    "FALSE",
}


@dataclass(frozen=True)
class Token:
    kind: str  # name, qname, string, number, keyword, op, eof
    value: Any
    text: str
    start: int
    end: int


_TWO_CHAR_OPS = {"<=", ">=", "<>", "!=", "||"}
_ONE_CHAR_OPS = set("=<>+-*/(),;")
_INT_TEXT_RE = re.compile(r"[0-9]+\Z")


def _syntax(message: str, position: Optional[int] = None) -> QueryError:
    if position is None:
        return QueryError("Syntax error: " + message)
    return QueryError("Syntax error at position %d: %s" % (position, message))


def tokenize(sql: str) -> List[Token]:
    if not isinstance(sql, str):
        raise QueryError("Query must be a string")

    tokens: List[Token] = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue

        start = i

        if c.isalpha() or c == "_":
            j = i + 1
            while j < n and (sql[j].isalnum() or sql[j] == "_"):
                j += 1
            word = sql[i:j]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token("keyword", upper, word, start, j))
            else:
                tokens.append(Token("name", word, word, start, j))
            i = j
            continue

        if c == '"':
            j = i + 1
            chars = []
            while j < n:
                if sql[j] == '"':
                    if j + 1 < n and sql[j + 1] == '"':
                        chars.append('"')
                        j += 2
                        continue
                    j += 1
                    break
                chars.append(sql[j])
                j += 1
            else:
                raise _syntax("unterminated quoted name", start)
            tokens.append(Token("qname", "".join(chars), sql[start:j], start, j))
            i = j
            continue

        if c == "'":
            j = i + 1
            chars = []
            while j < n:
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        chars.append("'")
                        j += 2
                        continue
                    j += 1
                    break
                chars.append(sql[j])
                j += 1
            else:
                raise _syntax("unterminated string literal", start)
            tokens.append(Token("string", "".join(chars), sql[start:j], j - len(chars) - 2, j))
            # The token's start was already recorded; keep it simple below.
            tokens[-1] = Token("string", tokens[-1].value, sql[start:j], start, j)
            i = j
            continue

        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            j = i
            while j < n and sql[j].isdigit():
                j += 1
            if j < n and sql[j] == ".":
                j += 1
                while j < n and sql[j].isdigit():
                    j += 1
            text = sql[i:j]
            value = float(text) if "." in text else int(text)
            tokens.append(Token("number", value, text, start, j))
            i = j
            continue

        two = sql[i : i + 2]
        if two in _TWO_CHAR_OPS:
            tokens.append(Token("op", two, two, start, i + 2))
            i += 2
            continue

        if c in _ONE_CHAR_OPS:
            tokens.append(Token("op", c, c, start, i + 1))
            i += 1
            continue

        raise _syntax("unexpected character %r" % c, start)

    tokens.append(Token("eof", None, "", n, n))
    return tokens


# ---------------------------------------------------------------------------
# AST


@dataclass
class Literal:
    value: Any


@dataclass
class Column:
    name: str


@dataclass
class Unary:
    op: str  # neg, not
    operand: Any


@dataclass
class Binary:
    op: str  # or, and, =, !=, <, <=, >, >=, +, -, *, /, ||
    left: Any
    right: Any


@dataclass
class IsNull:
    operand: Any
    negated: bool


@dataclass
class InList:
    operand: Any
    items: List[Any]
    negated: bool


@dataclass
class Between:
    operand: Any
    low: Any
    high: Any
    negated: bool


@dataclass
class Like:
    operand: Any
    pattern: Any
    negated: bool


@dataclass
class Func:
    name: str
    args: List[Any] = field(default_factory=list)
    star: bool = False


@dataclass
class SelectItem:
    expr: Optional[Any]
    star: bool
    alias: Optional[str]
    text: str
    plain_name: Optional[str] = None


@dataclass
class OrderItem:
    expr: Any
    descending: bool
    text: str
    bare_integer: Optional[int] = None
    bare_name: Optional[str] = None


@dataclass
class Query:
    distinct: bool
    items: List[SelectItem]
    table: str
    where: Optional[Any] = None
    group_by: List[Any] = field(default_factory=list)
    having: Optional[Any] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: int = 0


# ---------------------------------------------------------------------------
# Parser


_COMPARISON_OPS = {"=", "!=", "<>", "<", "<=", ">", ">="}


class Parser:
    def __init__(self, sql: str):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.index = 0

    # -- token helpers ------------------------------------------------------

    def peek(self, offset: int = 0) -> Token:
        i = self.index + offset
        if i >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[i]

    def advance(self) -> Token:
        token = self.peek()
        if token.kind != "eof":
            self.index += 1
        return token

    def at_kw(self, keyword: str, offset: int = 0) -> bool:
        token = self.peek(offset)
        return token.kind == "keyword" and token.value == keyword

    def match_kw(self, keyword: str) -> bool:
        if self.at_kw(keyword):
            self.advance()
            return True
        return False

    def expect_kw(self, keyword: str) -> Token:
        if not self.at_kw(keyword):
            self.error("expected %s" % keyword)
        return self.advance()

    def at_op(self, op: str, offset: int = 0) -> bool:
        token = self.peek(offset)
        return token.kind == "op" and token.value == op

    def match_op(self, op: str) -> bool:
        if self.at_op(op):
            self.advance()
            return True
        return False

    def expect_op(self, op: str) -> Token:
        if not self.at_op(op):
            self.error("expected %r" % op)
        return self.advance()

    def expect_name(self, what: str) -> str:
        token = self.peek()
        if token.kind in ("name", "qname"):
            self.advance()
            return token.value
        self.error("expected %s" % what)

    def error(self, message: str) -> None:
        token = self.peek()
        if token.kind == "eof":
            raise _syntax(message + " at end of query", token.start)
        raise _syntax(message + " near %r" % token.text, token.start)

    # -- query --------------------------------------------------------------

    def parse(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.match_kw("DISTINCT")

        items: List[SelectItem] = []
        if self.at_op("*"):
            star = self.advance()
            items.append(SelectItem(None, True, None, star.text))
            if self.at_op(","):
                self.error("'*' must be the only select item")
        else:
            while True:
                items.append(self.parse_select_item())
                if self.match_op(","):
                    if self.at_op("*"):
                        self.error("'*' must be the only select item")
                    continue
                break

        self.expect_kw("FROM")
        table = self.expect_name("table name")

        where = None
        if self.match_kw("WHERE"):
            where = self.parse_expr()

        group_by: List[Any] = []
        if self.match_kw("GROUP"):
            self.expect_kw("BY")
            group_by.append(self.parse_expr())
            while self.match_op(","):
                group_by.append(self.parse_expr())

        having = None
        if self.match_kw("HAVING"):
            having = self.parse_expr()

        order_by: List[OrderItem] = []
        if self.match_kw("ORDER"):
            self.expect_kw("BY")
            order_by.append(self.parse_order_item())
            while self.match_op(","):
                order_by.append(self.parse_order_item())

        limit: Optional[int] = None
        offset = 0
        if self.match_kw("LIMIT"):
            limit = self.parse_nonnegative_integer("LIMIT")
            if self.match_kw("OFFSET"):
                offset = self.parse_nonnegative_integer("OFFSET")

        self.match_op(";")
        if self.peek().kind != "eof":
            self.error("unexpected token")

        return Query(
            distinct=distinct,
            items=items,
            table=table,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def parse_select_item(self) -> SelectItem:
        start_index = self.index
        expr = self.parse_expr()
        end_index = self.index - 1
        first = self.tokens[start_index]
        last = self.tokens[end_index]
        text = self.sql[first.start : last.end]

        plain_name = None
        if start_index == end_index and first.kind in ("name", "qname"):
            plain_name = first.value

        alias = None
        if self.match_kw("AS"):
            alias = self.expect_name("alias")
        elif self.peek().kind in ("name", "qname"):
            alias = self.advance().value

        return SelectItem(expr, False, alias, text, plain_name)

    def parse_order_item(self) -> OrderItem:
        start_index = self.index
        expr = self.parse_expr()
        end_index = self.index - 1
        first = self.tokens[start_index]
        last = self.tokens[end_index]
        text = self.sql[first.start : last.end]

        descending = False
        if self.match_kw("ASC"):
            descending = False
        elif self.match_kw("DESC"):
            descending = True

        bare_integer = None
        bare_name = None
        if start_index == end_index:
            token = first
            if token.kind == "number" and _INT_TEXT_RE.fullmatch(token.text):
                bare_integer = token.value
            elif token.kind in ("name", "qname"):
                bare_name = token.value

        return OrderItem(expr, descending, text, bare_integer, bare_name)

    def parse_nonnegative_integer(self, clause: str) -> int:
        token = self.peek()
        if token.kind == "number" and _INT_TEXT_RE.fullmatch(token.text):
            self.advance()
            return token.value
        self.error("%s requires a non-negative integer" % clause)

    # -- expressions --------------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.match_kw("OR"):
            right = self.parse_and()
            left = Binary("or", left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.match_kw("AND"):
            right = self.parse_not()
            left = Binary("and", left, right)
        return left

    def parse_not(self):
        if self.match_kw("NOT"):
            return Unary("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()

        if self.match_kw("IS"):
            negated = self.match_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(left, negated)

        negated = False
        if self.at_kw("NOT") and self.peek(1).kind == "keyword" and self.peek(1).value in (
            "IN",
            "BETWEEN",
            "LIKE",
        ):
            self.advance()
            negated = True

        if self.match_kw("IN"):
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.match_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return InList(left, items, negated)

        if self.match_kw("BETWEEN"):
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return Between(left, low, high, negated)

        if self.match_kw("LIKE"):
            pattern = self.parse_additive()
            return Like(left, pattern, negated)

        token = self.peek()
        if token.kind == "op" and token.value in _COMPARISON_OPS:
            op = self.advance().value
            if op == "<>":
                op = "!="
            right = self.parse_additive()
            return Binary(op, left, right)

        return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            token = self.peek()
            if token.kind == "op" and token.value in ("+", "-", "||"):
                op = self.advance().value
                right = self.parse_multiplicative()
                left = Binary(op, left, right)
            else:
                break
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            token = self.peek()
            if token.kind == "op" and token.value in ("*", "/"):
                op = self.advance().value
                right = self.parse_unary()
                left = Binary(op, left, right)
            else:
                break
        return left

    def parse_unary(self):
        if self.match_op("-"):
            return Unary("neg", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()

        if token.kind == "number":
            self.advance()
            return Literal(token.value)

        if token.kind == "string":
            self.advance()
            return Literal(token.value)

        if token.kind == "keyword":
            if token.value == "NULL":
                self.advance()
                return Literal(None)
            if token.value == "TRUE":
                self.advance()
                return Literal(True)
            if token.value == "FALSE":
                self.advance()
                return Literal(False)
            self.error("expected an expression")

        if token.kind in ("name", "qname"):
            self.advance()
            if self.at_op("("):
                return self.parse_func(token.value)
            return Column(token.value)

        if self.match_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr

        self.error("expected an expression")

    def parse_func(self, name: str) -> Func:
        self.expect_op("(")
        if self.at_op("*"):
            self.advance()
            self.expect_op(")")
            return Func(name, [], True)

        args = []
        if not self.at_op(")"):
            args.append(self.parse_expr())
            while self.match_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        return Func(name, args, False)


def parse(sql: str) -> Query:
    return Parser(sql).parse()


# ---------------------------------------------------------------------------
# AST helpers used by the engine


AGGREGATE_NAMES = {"count", "sum", "avg", "min", "max"}
SCALAR_ARITY = {
    "lower": (1, 1),
    "upper": (1, 1),
    "length": (1, 1),
    "abs": (1, 1),
    "round": (1, 2),
    "coalesce": (1, None),
}


def is_aggregate(node) -> bool:
    return isinstance(node, Func) and node.name.lower() in AGGREGATE_NAMES


def contains_aggregate(node) -> bool:
    if is_aggregate(node):
        return True
    for child in _children(node):
        if contains_aggregate(child):
            return True
    return False


def _children(node):
    if isinstance(node, Unary):
        return [node.operand]
    if isinstance(node, Binary):
        return [node.left, node.right]
    if isinstance(node, IsNull):
        return [node.operand]
    if isinstance(node, InList):
        return [node.operand] + list(node.items)
    if isinstance(node, Between):
        return [node.operand, node.low, node.high]
    if isinstance(node, Like):
        return [node.operand, node.pattern]
    if isinstance(node, Func):
        return list(node.args)
    return []


def literals_equal(a, b) -> bool:
    a_num = isinstance(a, (int, float)) and not isinstance(a, bool)
    b_num = isinstance(b, (int, float)) and not isinstance(b, bool)
    if a_num or b_num:
        return a_num and b_num and a == b
    return type(a) is type(b) and a == b


def expr_equal(a, b) -> bool:
    if type(a) is not type(b):
        return False
    if isinstance(a, Literal):
        return literals_equal(a.value, b.value)
    if isinstance(a, Column):
        return a.name.lower() == b.name.lower()
    if isinstance(a, Unary):
        return a.op == b.op and expr_equal(a.operand, b.operand)
    if isinstance(a, Binary):
        return a.op == b.op and expr_equal(a.left, b.left) and expr_equal(a.right, b.right)
    if isinstance(a, IsNull):
        return a.negated == b.negated and expr_equal(a.operand, b.operand)
    if isinstance(a, InList):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and len(a.items) == len(b.items)
            and all(expr_equal(x, y) for x, y in zip(a.items, b.items))
        )
    if isinstance(a, Between):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and expr_equal(a.low, b.low)
            and expr_equal(a.high, b.high)
        )
    if isinstance(a, Like):
        return (
            a.negated == b.negated
            and expr_equal(a.operand, b.operand)
            and expr_equal(a.pattern, b.pattern)
        )
    if isinstance(a, Func):
        return (
            a.name.lower() == b.name.lower()
            and a.star == b.star
            and len(a.args) == len(b.args)
            and all(expr_equal(x, y) for x, y in zip(a.args, b.args))
        )
    return False

