"""Query validation and execution for minisql."""

from __future__ import annotations

import csv
import math
import os
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from functools import cmp_to_key
from typing import Any, Dict, List, Optional, Tuple

from ._parser import (
    AGGREGATE_NAMES,
    SCALAR_ARITY,
    Between,
    Binary,
    Column,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    Query,
    QueryError,
    Unary,
    _children,
    contains_aggregate,
    expr_equal,
    is_aggregate,
    parse,
)


# ---------------------------------------------------------------------------
# Tables


@dataclass
class Table:
    name: str
    columns: List[str]
    rows: List[List[Any]]
    index_by_name: Dict[str, int]


_INT_RE = re.compile(r"-?[0-9]+\Z")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")


def _convert_field(text: str) -> Any:
    if text == "":
        return None
    if _INT_RE.fullmatch(text):
        return int(text)
    if _DECIMAL_RE.fullmatch(text):
        return float(text)
    return text


def load_table(name: str, directory: Any) -> Table:
    try:
        directory = os.fspath(directory)
    except TypeError:
        raise QueryError("Directory must be a filesystem path")

    path = os.path.join(directory, name + ".csv")
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as handle:
            reader = csv.reader(handle)
            try:
                header = next(reader)
            except StopIteration:
                header = []

            rows: List[List[Any]] = []
            for line_number, raw in enumerate(reader, start=2):
                if not raw:
                    # Ignore blank lines, which the csv module reports as [].
                    continue
                if len(raw) != len(header):
                    raise QueryError(
                        "Table %r row %d has %d fields, expected %d"
                        % (name, line_number, len(raw), len(header))
                    )
                rows.append([_convert_field(field) for field in raw])
    except FileNotFoundError:
        raise QueryError("Unknown table: %s" % name)
    except IsADirectoryError:
        raise QueryError("Table %r is not a file" % name)
    except UnicodeError as exc:
        raise QueryError("Cannot read table %r: %s" % (name, exc))
    except csv.Error as exc:
        raise QueryError("Cannot read table %r: %s" % (name, exc))
    except OSError as exc:
        raise QueryError("Cannot read table %r: %s" % (name, exc))

    index_by_name: Dict[str, int] = {}
    for index, column in enumerate(header):
        index_by_name.setdefault(column.lower(), index)

    return Table(name, header, rows, index_by_name)


# ---------------------------------------------------------------------------
# Validation


class _Validator:
    def __init__(self, table: Table):
        self.table = table

    def resolve_column(self, name: str) -> int:
        try:
            return self.table.index_by_name[name.lower()]
        except KeyError:
            raise QueryError("Unknown column: %s" % name)

    def validate(self, node: Any, context: str, inside_aggregate: bool = False) -> None:
        if isinstance(node, Literal):
            return
        if isinstance(node, Column):
            self.resolve_column(node.name)
            return
        if isinstance(node, Unary):
            self.validate(node.operand, context, inside_aggregate)
            return
        if isinstance(node, Binary):
            self.validate(node.left, context, inside_aggregate)
            self.validate(node.right, context, inside_aggregate)
            return
        if isinstance(node, IsNull):
            self.validate(node.operand, context, inside_aggregate)
            return
        if isinstance(node, InList):
            self.validate(node.operand, context, inside_aggregate)
            for item in node.items:
                self.validate(item, context, inside_aggregate)
            return
        if isinstance(node, Between):
            self.validate(node.operand, context, inside_aggregate)
            self.validate(node.low, context, inside_aggregate)
            self.validate(node.high, context, inside_aggregate)
            return
        if isinstance(node, Like):
            self.validate(node.operand, context, inside_aggregate)
            self.validate(node.pattern, context, inside_aggregate)
            return
        if isinstance(node, Func):
            name = node.name.lower()
            if name in AGGREGATE_NAMES:
                if context == "where":
                    raise QueryError("Aggregate functions are not allowed in WHERE")
                if context == "group_by":
                    raise QueryError("Aggregate functions are not allowed in GROUP BY")
                if inside_aggregate:
                    raise QueryError("Aggregate functions cannot be nested")
                self._check_aggregate_arity(name, node)
                for arg in node.args:
                    self.validate(arg, context, True)
                return
            if name in SCALAR_ARITY:
                if node.star:
                    raise QueryError("Function %s does not accept '*'" % node.name)
                minimum, maximum = SCALAR_ARITY[name]
                count = len(node.args)
                if count < minimum or (maximum is not None and count > maximum):
                    raise QueryError("Wrong number of arguments for %s" % node.name)
                for arg in node.args:
                    self.validate(arg, context, inside_aggregate)
                return
            raise QueryError("Unknown function: %s" % node.name)

        raise QueryError("Invalid expression")

    def _check_aggregate_arity(self, name: str, node: Func) -> None:
        if node.star:
            if name != "count":
                raise QueryError("Function %s does not accept '*'" % node.name)
            return
        if len(node.args) != 1:
            raise QueryError("Wrong number of arguments for %s" % node.name)


def _validate_grouped_expression(node: Any, group_by: List[Any]) -> None:
    if is_aggregate(node):
        return
    for grouped in group_by:
        if expr_equal(node, grouped):
            return
    if isinstance(node, Column):
        raise QueryError(
            "Column %r must appear in GROUP BY or be used in an aggregate" % node.name
        )
    for child in _children(node):
        _validate_grouped_expression(child, group_by)


# ---------------------------------------------------------------------------
# Value semantics


def _is_number(value: Any) -> bool:
    return type(value) is int or type(value) is float


def _as_boolean(value: Any, what: str) -> Optional[bool]:
    if value is None:
        return None
    if type(value) is bool:
        return value
    raise QueryError("%s must be a boolean" % what)


def _and3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is False or right is False:
        return False
    if left is None or right is None:
        return None
    return True


def _or3(left: Optional[bool], right: Optional[bool]) -> Optional[bool]:
    if left is True or right is True:
        return True
    if left is None or right is None:
        return None
    return False


def _not3(value: Optional[bool]) -> Optional[bool]:
    if value is None:
        return None
    return not value


def _describe(value: Any) -> str:
    if value is None:
        return "NULL"
    if type(value) is bool:
        return "boolean"
    if _is_number(value):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def _compare(left: Any, right: Any) -> int:
    if isinstance(left, bool) or isinstance(right, bool):
        if type(left) is not bool or type(right) is not bool:
            raise QueryError("Cannot compare %s with %s" % (_describe(left), _describe(right)))
        return (left > right) - (left < right)

    if _is_number(left) and _is_number(right):
        return (left > right) - (left < right)

    if isinstance(left, str) and isinstance(right, str):
        return (left > right) - (left < right)

    raise QueryError("Cannot compare %s with %s" % (_describe(left), _describe(right)))


def _compare_op(op: str, left: Any, right: Any) -> Optional[bool]:
    if left is None or right is None:
        return None
    comparison = _compare(left, right)
    if op == "=":
        return comparison == 0
    if op == "!=":
        return comparison != 0
    if op == "<":
        return comparison < 0
    if op == "<=":
        return comparison <= 0
    if op == ">":
        return comparison > 0
    if op == ">=":
        return comparison >= 0
    raise QueryError("Unknown comparison operator %s" % op)


def _arithmetic(op: str, left: Any, right: Any) -> Any:
    if left is None or right is None:
        return None
    if not _is_number(left) or not _is_number(right):
        raise QueryError("Arithmetic on %s and %s is not allowed" % (_describe(left), _describe(right)))

    if op == "/":
        if right == 0:
            return None
        try:
            return left / right
        except OverflowError:
            raise QueryError("Division result is out of range")

    if op == "+":
        result = left + right
    elif op == "-":
        result = left - right
    elif op == "*":
        result = left * right
    else:
        raise QueryError("Unknown arithmetic operator %s" % op)

    if type(left) is int and type(right) is int:
        return int(result)
    return float(result)


def _negate(value: Any) -> Any:
    if value is None:
        return None
    if not _is_number(value):
        raise QueryError("Unary '-' requires a number")
    return -value


def _concat(left: Any, right: Any) -> Any:
    if left is None or right is None:
        return None
    pieces = []
    for value in (left, right):
        if isinstance(value, str):
            pieces.append(value)
        elif _is_number(value):
            pieces.append(str(value))
        else:
            raise QueryError("'||' requires strings or numbers")
    return pieces[0] + pieces[1]


def _like_matches(value: Any, pattern: Any) -> bool:
    if not isinstance(value, str) or not isinstance(pattern, str):
        raise QueryError("LIKE requires string operands")
    pieces = []
    for character in pattern:
        if character == "%":
            pieces.append(".*")
        elif character == "_":
            pieces.append(".")
        else:
            pieces.append(re.escape(character))
    return re.fullmatch("".join(pieces), value, re.DOTALL) is not None


def _round_value(value: Any, places: Optional[int]) -> Any:
    if not _is_number(value):
        raise QueryError("ROUND requires a number")
    if isinstance(value, float) and (math.isnan(value) or math.isinf(value)):
        raise QueryError("ROUND requires a finite number")

    decimal_value = Decimal(value) if type(value) is int else Decimal(str(value))
    try:
        with localcontext() as context:
            context.prec = max(28, len(decimal_value.as_tuple().digits) + abs(places or 0) + 10)
            if places is None:
                rounded = decimal_value.quantize(Decimal(1), rounding=ROUND_HALF_UP)
                return int(rounded)
            quantum = Decimal(1).scaleb(-places)
            rounded = decimal_value.quantize(quantum, rounding=ROUND_HALF_UP)
            return float(rounded)
    except (InvalidOperation, ValueError, OverflowError):
        raise QueryError("ROUND result is out of range")


def _value_key(value: Any):
    if value is None:
        return (0,)
    if type(value) is bool:
        return (1, value)
    if _is_number(value):
        return (2, value)
    if isinstance(value, str):
        return (3, value)
    return (4, repr(value))


def _group_key(value: Any):
    if value is None:
        return (0, None)
    if type(value) is bool:
        return (1, value)
    if _is_number(value):
        return (2, value)
    if isinstance(value, str):
        return (3, value)
    return (4, repr(value))


# ---------------------------------------------------------------------------
# Expression evaluation


class _Evaluator:
    def __init__(self, table: Table):
        self.table = table

    def eval(self, node: Any, row: Optional[List[Any]], group: Optional[List[List[Any]]]) -> Any:
        if isinstance(node, Literal):
            return node.value
        if isinstance(node, Column):
            index = self.table.index_by_name.get(node.name.lower())
            if index is None:
                raise QueryError("Unknown column: %s" % node.name)
            if row is None:
                raise QueryError("Column %r is not available in this context" % node.name)
            return row[index]
        if isinstance(node, Unary):
            if node.op == "neg":
                return _negate(self.eval(node.operand, row, group))
            value = _as_boolean(self.eval(node.operand, row, group), "NOT operand")
            return _not3(value)
        if isinstance(node, Binary):
            if node.op in ("and", "or"):
                left = _as_boolean(self.eval(node.left, row, group), "AND/OR operand")
                right = _as_boolean(self.eval(node.right, row, group), "AND/OR operand")
                if node.op == "and":
                    return _and3(left, right)
                return _or3(left, right)
            left = self.eval(node.left, row, group)
            right = self.eval(node.right, row, group)
            if node.op in ("=", "!=", "<", "<=", ">", ">="):
                return _compare_op(node.op, left, right)
            if node.op in ("+", "-", "*", "/"):
                return _arithmetic(node.op, left, right)
            if node.op == "||":
                return _concat(left, right)
            raise QueryError("Unknown operator %s" % node.op)
        if isinstance(node, IsNull):
            result = self.eval(node.operand, row, group) is None
            return not result if node.negated else result
        if isinstance(node, InList):
            operand = self.eval(node.operand, row, group)
            items = [self.eval(item, row, group) for item in node.items]
            result = self._in(operand, items)
            return _not3(result) if node.negated else result
        if isinstance(node, Between):
            operand = self.eval(node.operand, row, group)
            low = self.eval(node.low, row, group)
            high = self.eval(node.high, row, group)
            result = _and3(
                _compare_op("<=", low, operand),
                _compare_op("<=", operand, high),
            )
            return _not3(result) if node.negated else result
        if isinstance(node, Like):
            operand = self.eval(node.operand, row, group)
            pattern = self.eval(node.pattern, row, group)
            if operand is None or pattern is None:
                result = None
            else:
                result = _like_matches(operand, pattern)
            return _not3(result) if node.negated else result
        if isinstance(node, Func):
            name = node.name.lower()
            if name in AGGREGATE_NAMES:
                if group is None:
                    raise QueryError("Aggregate function %s is not allowed here" % node.name)
                return self._aggregate(name, node, group)
            return self._scalar(name, node, row, group)

        raise QueryError("Invalid expression")

    @staticmethod
    def _in(operand: Any, items: List[Any]) -> Optional[bool]:
        if operand is None:
            return None
        saw_null = False
        for item in items:
            if item is None:
                saw_null = True
                continue
            if _compare(operand, item) == 0:
                return True
        return None if saw_null else False

    def _aggregate(self, name: str, node: Func, rows: List[List[Any]]) -> Any:
        if name == "count":
            if node.star:
                return len(rows)
            count = 0
            for row in rows:
                if self.eval(node.args[0], row, None) is not None:
                    count += 1
            return count

        values = [self.eval(node.args[0], row, None) for row in rows]
        values = [value for value in values if value is not None]

        if name == "sum":
            if not values:
                return None
            total = 0
            use_float = False
            for value in values:
                if not _is_number(value):
                    raise QueryError("SUM requires numeric values")
                if type(value) is float:
                    use_float = True
                total += value
            return float(total) if use_float else total

        if name == "avg":
            if not values:
                return None
            total = 0
            for value in values:
                if not _is_number(value):
                    raise QueryError("AVG requires numeric values")
                total += value
            return total / len(values)

        if name in ("min", "max"):
            if not values:
                return None
            best = values[0]
            for value in values[1:]:
                comparison = _compare(value, best)
                if name == "min" and comparison < 0:
                    best = value
                elif name == "max" and comparison > 0:
                    best = value
            return best

        raise QueryError("Unknown aggregate function: %s" % name)

    def _scalar(
        self,
        name: str,
        node: Func,
        row: Optional[List[Any]],
        group: Optional[List[List[Any]]],
    ) -> Any:
        if name == "coalesce":
            for argument in node.args:
                value = self.eval(argument, row, group)
                if value is not None:
                    return value
            return None

        values = [self.eval(argument, row, group) for argument in node.args]
        if any(value is None for value in values):
            return None

        if name in ("lower", "upper", "length"):
            value = values[0]
            if not isinstance(value, str):
                raise QueryError("%s requires a string" % name.upper())
            if name == "lower":
                return value.lower()
            if name == "upper":
                return value.upper()
            return len(value)

        if name == "abs":
            value = values[0]
            if not _is_number(value):
                raise QueryError("ABS requires a number")
            return abs(value)

        if name == "round":
            value = values[0]
            if len(values) == 1:
                return _round_value(value, None)
            places = values[1]
            if type(places) is not int:
                raise QueryError("ROUND's second argument must be an integer")
            return _round_value(value, places)

        raise QueryError("Unknown function: %s" % node.name)


# ---------------------------------------------------------------------------
# Execution


def _expand_select(query: Query, table: Table, validator: _Validator) -> Tuple[List[Any], List[str]]:
    expressions: List[Any] = []
    columns: List[str] = []
    for item in query.items:
        if item.star:
            for column in table.columns:
                expressions.append(Column(column))
                columns.append(column)
            continue

        expressions.append(item.expr)
        if item.alias is not None:
            columns.append(item.alias)
        elif item.plain_name is not None:
            index = validator.resolve_column(item.plain_name)
            columns.append(table.columns[index])
        else:
            columns.append(item.text)
    return expressions, columns


def _resolve_order(
    query: Query, columns: List[str], validator: _Validator
) -> List[Tuple[bool, Optional[int], Optional[Any]]]:
    names: Dict[str, int] = {}
    for index, column in enumerate(columns):
        names.setdefault(column.lower(), index)

    resolved = []
    for item in query.order_by:
        if item.bare_integer is not None:
            position = item.bare_integer
            if position < 1 or position > len(columns):
                raise QueryError("ORDER BY position %d is out of range" % position)
            resolved.append((item.descending, position - 1, None))
        elif item.bare_name is not None and item.bare_name.lower() in names:
            resolved.append((item.descending, names[item.bare_name.lower()], None))
        else:
            validator.validate(item.expr, "order_by")
            resolved.append((item.descending, None, item.expr))
    return resolved


def execute(sql: str, directory: Any) -> "Result":
    query = parse(sql)
    table = load_table(query.table, directory)
    validator = _Validator(table)

    select_expressions, columns = _expand_select(query, table, validator)

    if query.where is not None:
        validator.validate(query.where, "where")
    for expression in query.group_by:
        validator.validate(expression, "group_by")
    for expression in select_expressions:
        validator.validate(expression, "select")
    if query.having is not None:
        validator.validate(query.having, "having")

    order = _resolve_order(query, columns, validator)

    grouped = bool(query.group_by)
    if not grouped and any(contains_aggregate(expression) for expression in select_expressions):
        grouped = True
    if not grouped and query.having is not None and contains_aggregate(query.having):
        grouped = True
    if not grouped:
        for _, output_index, expression in order:
            if output_index is None and contains_aggregate(expression):
                grouped = True
                break

    if grouped:
        for expression in select_expressions:
            _validate_grouped_expression(expression, query.group_by)
        if query.having is not None:
            _validate_grouped_expression(query.having, query.group_by)
        for _, output_index, expression in order:
            if output_index is None:
                _validate_grouped_expression(expression, query.group_by)

    evaluator = _Evaluator(table)

    rows = table.rows
    if query.where is not None:
        filtered = []
        for row in rows:
            value = evaluator.eval(query.where, row, None)
            if _as_boolean(value, "WHERE condition") is True:
                filtered.append(row)
        rows = filtered

    # Each entry is (output values, representative row, group rows).
    entries: List[Tuple[Tuple[Any, ...], Optional[List[Any]], Optional[List[List[Any]]]]] = []

    if grouped:
        if query.group_by:
            groups: Dict[Any, List[List[Any]]] = {}
            for row in rows:
                key = tuple(
                    _group_key(evaluator.eval(expression, row, None))
                    for expression in query.group_by
                )
                groups.setdefault(key, []).append(row)
            group_rows_list = list(groups.values())
        else:
            # A single group, even when there are no input rows.
            group_rows_list = [rows]

        for group_rows in group_rows_list:
            representative = group_rows[0] if group_rows else None
            if query.having is not None:
                value = evaluator.eval(query.having, representative, group_rows)
                if _as_boolean(value, "HAVING condition") is not True:
                    continue
            values = tuple(
                evaluator.eval(expression, representative, group_rows)
                for expression in select_expressions
            )
            entries.append((values, representative, group_rows))
    else:
        for row in rows:
            if query.having is not None:
                value = evaluator.eval(query.having, row, None)
                if _as_boolean(value, "HAVING condition") is not True:
                    continue
            values = tuple(
                evaluator.eval(expression, row, None) for expression in select_expressions
            )
            entries.append((values, row, None))

    if query.distinct:
        seen = set()
        kept = []
        for entry in entries:
            key = tuple(_value_key(value) for value in entry[0])
            if key not in seen:
                seen.add(key)
                kept.append(entry)
        entries = kept

    if order:
        decorated = []
        for values, row, group in entries:
            keys = []
            for _, output_index, expression in order:
                if output_index is not None:
                    keys.append(values[output_index])
                else:
                    keys.append(evaluator.eval(expression, row, group))
            decorated.append((values, keys))

        def compare(left, right):
            for (descending, _, _), left_value, right_value in zip(
                order, left[1], right[1]
            ):
                if left_value is None:
                    if right_value is None:
                        continue
                    return 1 if descending else -1
                if right_value is None:
                    return -1 if descending else 1
                comparison = _compare(left_value, right_value)
                if comparison:
                    return -comparison if descending else comparison
            return 0

        decorated.sort(key=cmp_to_key(compare))
        output_rows = [entry[0] for entry in decorated]
    else:
        output_rows = [entry[0] for entry in entries]

    if query.limit is not None:
        output_rows = output_rows[query.offset : query.offset + query.limit]
    elif query.offset:
        output_rows = output_rows[query.offset :]

    return Result(columns, output_rows)


class Result:
    """The result of a query: output columns and rows."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns: List[str], rows: List[Tuple[Any, ...]]):
        self.columns = columns
        self.rows = rows

    def __repr__(self) -> str:
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

