"""Command-line interface for minisql."""

import argparse
import csv
import sys

from . import QueryError, run


def _format(value):
    if value is None:
        return ""
    if type(value) is bool:
        return "true" if value else "false"
    return str(value)


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="python -m minisql",
        description="Run a SELECT query against CSV files in a directory.",
    )
    parser.add_argument("query", help="SQL SELECT query to run")
    parser.add_argument(
        "--dir",
        default=".",
        metavar="DIR",
        help="directory containing the CSV files (default: current directory)",
    )
    args = parser.parse_args(argv)

    try:
        result = run(args.query, args.dir)
    except QueryError as exc:
        print(str(exc), file=sys.stderr)
        return 1

    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    for row in result.rows:
        writer.writerow([_format(value) for value in row])
    return 0


if __name__ == "__main__":
    sys.exit(main())

